void sort(apvector<int> & v) {
  int max;
  for (int i=v.length();i>=1;--i){
    max=i-1;
    for (int j=i-2; j>=0; --j)
      if(v[j]>v[max]) max=j;
    swap(v[i-1],v[max]);
  }
}

